char c1 = 10;
short s2 = 2000;
// Integral Promotion Rule: c1 and s2 are promoted to 'int'.
// Calculation uses native register width (e.g., 32-bit).
auto result = c1 + s2; // decltype(result) is int

unsigned char uc = 255;
// Promotion during assignment/initialization:
int i = uc; // 'uc' promoted to 'int' (Value 255)

// The Unsigned Trap (Standard Conversion Rank Rule):
short signed_val = -1;
unsigned int unsigned_val = 5;
// signed_val converted to unsigned int (large positive number)
bool comparison_trap = (signed_val > unsigned_val); // true

// Explicit Narrowing Conversion (Potential assembly truncation):
long long big = 0xDEADBEEF;
int small = (int)big; // High bits discarded (implementation defined value)
